import {escapeHtml as h,number} from './domain.js';
import {planetArt,badge,shipArt} from './art.js';
import {unitLevel} from './unit-levels.js';
const units=[['soldiers','Soldats'],['scouts','Scouts'],['bombers','Bombardiers'],['fighters','Destroyers']];
const hasAllies=group=>units.some(([key])=>Number(group?.before?.[key])>0||Number(group?.after?.[key])>0);
const date=v=>new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v));
const total=values=>units.reduce((sum,[key])=>sum+Number(values?.[key]||0),0);
const losses=group=>group?.before&&group?.after?units.reduce((sum,[key])=>sum+Math.max(0,Number(group.before[key]||0)-Number(group.after[key]||0)),0):null;
export function reportStatus(r){const d=r.details||{};if(d.outcome&&['combat','victory','defeat','conquest'].includes(d.outcome))return d.outcome;if(d.captured)return 'conquest';if(r.event==='capture')return d.mission==='defend'?'defeat':'victory';return r.event==='battle'?'combat':r.event;}
const labels={combat:'Combat',victory:'Victoire',defeat:'Défaite',conquest:'Conquête',arrival:'Arrivée',takeover:'Prise de contrôle'};
function cell(before,after){const loss=before==null||after==null?null:Math.max(0,Number(before)-Number(after));return `<span class="report-matrix-cell ${loss?'has-losses':''}"><b class="${loss?'remaining-hit':''}">${after==null?'—':number(after)}</b><small>/ ${before==null?'—':number(before)}</small><em class="casualty ${loss?'loss-hit':''}">${loss==null?'—':loss?'−'+number(loss):'0'}</em></span>`;}
function tally(c){const group=c.group,engaged=total(group.before),lost=losses(group);return `<section class="report-side ${c.tone}"><h3>${c.name}</h3>${lost==null?'<small>Pertes non enregistrées dans cet ancien rapport.</small>':`<div class="report-tally ${lost?'has-losses':''}"><span><b>${number(total(group.after))}</b> survivants / ${number(engaged)}</span><progress value="${Math.max(0,total(group.after))}" max="${Math.max(1,engaged)}" aria-label="Forces survivantes"></progress><span><b>${lost?'−':''}${number(lost)}</b> pertes · ${engaged?new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}).format(100*lost/engaged):0} %</span></div>`}</section>`;}
function forceMatrix(camps,race){return `<div class="report-force-matrix" style="--report-camps:${camps.length}"><div class="report-matrix-row report-matrix-head"><span>Restantes / engagées · pertes</span>${camps.map(c=>`<b class="${c.tone}">${c.name}</b>`).join('')}</div>${units.map(([key,label])=>{const groups=new Map();for(const c of camps)for(const g of c.group.before?.units||[])if(g.unit===key&&Number(g.quantity)>0)groups.set(g.race+':'+g.level,g);return `<details class="report-unit"><summary class="report-matrix-row"><span class="report-unit-title"><i aria-hidden="true">›</i>${key==='soldiers'?badge('race',race):shipArt(race,key==='scouts'?'scout':key==='bombers'?'bomber':'fighter')}${label}</span>${camps.map(c=>cell(c.group.before?.[key],c.group.after?.[key])).join('')}</summary><div class="report-unit-breakdown">${groups.size?[...groups.values()].map(g=>`<div class="report-matrix-row"><span class="report-cohort">${badge('race',g.race)}${h(g.race?.charAt(0).toUpperCase()+g.race?.slice(1)||'—')}${unitLevel(g.level)}</span>${camps.map(c=>{const match=x=>x.unit===key&&x.race===g.race&&x.level===g.level,b=c.group.before?.units?.find(match),a=c.group.after?.units?.find(match);return b?cell(b.quantity,a?.quantity??0):'<span class="report-absent">·</span>';}).join('')}</div>`).join(''):'<p>Niveau technologique non enregistré dans cet ancien rapport.</p>'}</div></details>`;}).join('')}</div>`;}
export function reportCard(r,unreadIds=[]){
 const d=r.details||{},s=d.sides,appearance=planetArt(r.appearance,true),race=String(r.appearance||'elys').split('_')[0],status=reportStatus(r),combat=['battle','capture'].includes(r.event),own=s?.own||{before:d.before,after:d.after},enemy=s?.enemies||{before:{...d.enemy_space,soldiers:d.enemy_ground}},camps=[{name:'Vos forces',tone:'own',group:own},...(hasAllies(s?.allies)?[{name:'Forces alliées',tone:'allied',group:s.allies}]:[]),{name:'Forces ennemies',tone:'hostile',group:enemy}],ownLoss=losses(own),enemyLoss=losses(enemy);
 const body=combat?`<p class="report-outcome">${status==='conquest'?'Planète conquise':status==='defeat'?'Planète perdue':d.mission==='attack'?'Vos forces en attaque':'Vos forces en défense'}</p>${d.opponents?.length?`<div class="report-opponents">${d.opponents.map(o=>`<span>${badge('race',o.race)}<b>${h(o.name)}</b>${o.origin?` · ${h(o.origin)}`:''}</span>`).join('')}</div>`:''}<div class="report-tallies">${camps.map(tally).join('')}</div>${forceMatrix(camps,race)}${enemy.before?.soldiers==null?'<small>Forces au sol non observées.</small>':''}`:r.event==='takeover'?`<p>Nouveau propriétaire : ${h(d.new_owner||'Inconnu')}.</p>`:`<p>${h(d.fleet||'Renforts')} a rejoint ce monde en ${d.mission==='attack'?'attaque':'défense'}.${d.teleport?' Soldats indisponibles pendant une heure.':d.lands_at?` Débarquement après ${date(d.lands_at)}.`:''}</p>`;
 return `<details class="battle-report visual-report ${unreadIds.includes(r.id)?'is-unread':''}"><summary><i class="report-chevron" aria-hidden="true">›</i>${appearance?`<img class="report-world" src="${appearance}" alt="" width="44" height="44">`:''}<span class="report-identity"><b>${h(r.planet||'Planète')}</b><small>${combat?(d.mission==='attack'?'Attaque':'Défense'):'Mouvement des forces'}</small></span><span class="report-status ${h(status)}">${labels[status]||'Opération'}</span>${combat?`<span class="report-loss-summary"><small>Pertes</small><b class="${ownLoss?'loss':''}">${ownLoss==null?'—':'−'+number(ownLoss)}</b> vous <span>·</span> <b>${enemyLoss==null?'—':'−'+number(enemyLoss)}</b> eux</span>`:''}<time datetime="${h(r.occurred_at)}">${date(r.occurred_at)}</time></summary><div class="report-body">${body}</div></details>`;
}
export function battleReportsView(data,unreadIds=[],history={}){
 const page=history.response||data?.report_page,items=page?.items||(data?.reports||[]).filter(r=>['battle','capture','arrival','takeover'].includes(r.event)).slice(0,15);
 return `<section class="battle-reports"><div class="military-section-heading"><div><span class="eyebrow">JOURNAL DES OPÉRATIONS</span><h2>Rapports de bataille</h2></div><span>Page ${Number(history.page)||1}</span></div>${history.error?`<p class="form-error" role="alert">${h(history.error)}</p>`:''}${items.length?items.map(r=>reportCard(r,unreadIds)).join(''):'<p class="empty">Aucun engagement signalé.</p>'}<nav class="report-pagination" aria-label="Pages des rapports"><button class="secondary" data-report-page="previous" ${!history.stack?.length||history.loading?'disabled':''}>Précédents</button><span>${items.length} rapport${items.length>1?'s':''}</span><button class="secondary" data-report-page="next" ${!page?.has_more||history.loading?'disabled':''}>Suivants</button></nav></section>`;
}
export function recentBattlesView(data){const reports=data?.recent_battles||(data?.reports||[]).filter(r=>['battle','capture'].includes(r.event)).slice(0,5);return `<section class="battle-reports recent-battles"><div class="military-section-heading"><h2>Derniers combats</h2><button class="text-button" data-page="alerts">Tous les rapports</button></div>${reports.length?reports.map(r=>reportCard(r)).join(''):'<p class="empty">Aucun combat enregistré.</p>'}</section>`;}
